package com.meetspace.cache; import com.meetspace.dto.EmployeeDtos.Profile; import org.springframework.stereotype.Component; import java.util.*;
@Component public class EmployeeIndex {private final Set<UUID> ids=new HashSet<>();private final Map<UUID,Profile> entries=new HashMap<>();public synchronized boolean contains(UUID id){return ids.contains(id);}public synchronized Optional<Profile> get(UUID id){return Optional.ofNullable(entries.get(id));}public synchronized void put(Profile p){ids.add(p.id());entries.put(p.id(),p);}public synchronized void remove(UUID id){ids.remove(id);entries.remove(id);}public synchronized void clear(){ids.clear();entries.clear();}public synchronized int size(){return entries.size();}}